begin;
alter table public.places add column if not exists neighborhood text not null default 'West Village';
alter table public.places add column if not exists latitude double precision;
alter table public.places add column if not exists longitude double precision;
alter table public.places add column if not exists coordinate_source_url text;
alter table public.places drop constraint if exists places_kind_check;
alter table public.places add constraint places_kind_check check (kind in ('coffee','park','library','garden','bookshop','landmark','gallery'));
-- Original catalogue rows and generations remain intact.
update public.places set neighborhood='West Village',latitude=40.7349281,longitude=-74.0022788,coordinate_source_url='https://www.openstreetmap.org/node/4909655521' where id='partners-village';
update public.places set neighborhood='West Village',latitude=40.738363,longitude=-74.00023,coordinate_source_url='https://www.openstreetmap.org/way/250490712' where id='birch-village';
update public.places set neighborhood='West Village',latitude=40.734588,longitude=-73.999192,coordinate_source_url='https://www.openstreetmap.org/way/249664014' where id='jefferson-library';
update public.places set neighborhood='West Village',latitude=40.7344521,longitude=-73.9994809,coordinate_source_url='https://www.openstreetmap.org/way/239988120' where id='jefferson-garden';
update public.places set neighborhood='West Village',latitude=40.7312348,longitude=-73.9971025,coordinate_source_url='https://www.openstreetmap.org/way/248166269' where id='washington-square';
on conflict (id) do update set name=excluded.name,kind=excluded.kind,address=excluded.address,description=excluded.description,visit_note=excluded.visit_note,source_url=excluded.source_url,neighborhood=excluded.neighborhood,latitude=excluded.latitude,longitude=excluded.longitude,coordinate_source_url=excluded.coordinate_source_url,verified_on=excluded.verified_on;
-- The existing RLS and read-only catalogue grants stay in force.
commit;
select neighborhood,count(*) as places,count(*) filter (where kind='coffee') as coffee_starts from public.places group by neighborhood order by neighborhood;
